Here's a Python script that simulates keyboard input in a virtual sandbox environment. It records key presses and sends them to a server for analysis.

```python
import asyncio
import aiohttp
import json
import time

class KeyboardActionLogger:
    def __init__(self):
        self.logger = asyncio.get_event_loop().run_until_complete(
            self.record_key_presses()
        )

    async def record_key_presses(self):
        async with self.logger:
            while True:
                try:
                    key = await asyncio.wait(aiohttp.get(f"http://localhost:8080/api/keyboard/press"))
                    if key.status == 200:
                        data = json.loads(key.text)
                        self.logger.info(f"Key {data['key']} pressed")
                except Exception as e:
                    self.logger.error(f"Error recording key: {e}")
                    await asyncio.sleep(0.5)

if __name__ == "__main__":
    logger = KeyboardActionLogger()
    asyncio.run(logger.record_key_presses())
